-- ============================================
-- LUMA — Enrichissement Thématique 8 (Fantastique) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"sage": "le sage du village", "guardian": "le gardien de la caverne"}, "start_node": "n1", "nodes": {"n1": {"speaker": "sage", "text": "The Amulet of Light was stolen and hidden in the Whispering Caves. Will you retrieve it?", "text_fr": "L''Amulette de Lumière a été volée et cachée dans les Grottes Murmurantes. Irez-vous la récupérer ?", "choices": [{"text": "Tell me what dangers await inside.", "next": "n2"}, {"text": "I accept, I''ll leave at once.", "next": "n2b"}, {"text": "What''s in it for me if I succeed?", "next": "n2c"}]}, "n2": {"speaker": "sage", "text": "A guardian protects it, one who values wisdom over strength.", "text_fr": "Un gardien la protège, qui valorise la sagesse plutôt que la force.", "choices": [{"text": "Then I''ll prepare my mind, not just my sword.", "next": "n3"}]}, "n2b": {"speaker": "sage", "text": "Bold as ever. May the light guide you.", "text_fr": "Toujours aussi audacieux. Que la lumière vous guide.", "choices": [{"text": "I won''t disappoint you.", "next": "n3"}]}, "n2c": {"speaker": "sage", "text": "Fair question. The village''s gratitude, and a share of its treasury.", "text_fr": "Question légitime. La gratitude du village, et une part de son trésor.", "choices": [{"text": "That''s a fair deal, I accept.", "next": "n3"}]}, "n3": {"speaker": "guardian", "text": "Halt! Only those who answer truthfully may pass. Why do you seek the amulet?", "text_fr": "Halte ! Seuls ceux qui répondent avec vérité peuvent passer. Pourquoi cherchez-vous l''amulette ?", "choices": [{"text": "To restore light and hope to my village.", "next": "n4"}, {"text": "For the glory and reward it would bring me.", "next": "n4b"}, {"text": "I''m honestly not entirely sure yet.", "next": "n4c"}]}, "n4": {"speaker": "guardian", "text": "A pure heart. But tell me — what would you sacrifice to protect your village?", "text_fr": "Un cœur pur. Mais dites-moi — que sacrifieriez-vous pour protéger votre village ?", "choices": [{"text": "Anything, even my own safety.", "next": "n5"}]}, "n4b": {"speaker": "guardian", "text": "Honesty, at least. Perhaps that is enough for a smaller trial.", "text_fr": "L''honnêteté, au moins. Peut-être est-ce suffisant pour une épreuve plus modeste.", "choices": [{"text": "I''m ready for whatever trial you have.", "next": "n5b"}]}, "n4c": {"speaker": "guardian", "text": "Uncertainty itself can be a kind of honesty. Let''s see what you discover about yourself here.", "text_fr": "L''incertitude elle-même peut être une forme d''honnêteté. Voyons ce que vous découvrirez ici sur vous-même.", "choices": [{"text": "I''m ready to find out.", "next": "n5c"}]}, "n5": {"speaker": "guardian", "text": "Then face the trial of flame — walk through without fear.", "text_fr": "Alors affrontez l''épreuve des flammes — traversez sans crainte.", "choices": [{"text": "(walk through, trusting the guardian''s judgment)", "next": "end_pure"}]}, "n5b": {"speaker": "guardian", "text": "Face the trial of shadows — find your way through the darkness alone.", "text_fr": "Affrontez l''épreuve des ombres — trouvez votre chemin dans l''obscurité seul.", "choices": [{"text": "(navigate carefully through the shadows)", "next": "end_honest"}]}, "n5c": {"speaker": "guardian", "text": "Face the trial of the mirror — see only the truth of yourself.", "text_fr": "Affrontez l''épreuve du miroir — ne voyez que la vérité sur vous-même.", "choices": [{"text": "(look into the mirror and accept what you see)", "next": "end_discovery"}]}, "end_pure": {"speaker": "guardian", "text": "Go, and let the light shine upon your village once more.", "text_fr": "Allez, et que la lumière brille de nouveau sur votre village.", "end": true, "ending_label": "Quête accomplie avec honneur 🏆"}, "end_honest": {"speaker": "guardian", "text": "You made it through. Take it, but remember what true worth means.", "text_fr": "Vous avez réussi. Prenez-la, mais souvenez-vous de ce que vaut vraiment la vraie valeur.", "end": true, "ending_label": "Quête accomplie avec réserve 🔶"}, "end_discovery": {"speaker": "guardian", "text": "You now know yourself better than when you arrived. Take the amulet — you''ve earned it.", "text_fr": "Vous vous connaissez mieux maintenant qu''à votre arrivée. Prenez l''amulette — vous l''avez méritée.", "end": true, "ending_label": "Quête de découverte de soi accomplie 🪞✨"}}}'::jsonb, is_playable = true
where title = 'Une quête complète pour retrouver un artefact'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"king": "le roi Aldric", "queen": "la reine Yssa"}, "start_node": "n1", "nodes": {"n1": {"speaker": "king", "text": "Our kingdoms have been at odds for years. What do you propose to unite us?", "text_fr": "Nos royaumes sont en conflit depuis des années. Que proposez-vous pour nous unir ?", "choices": [{"text": "A trade agreement that benefits both lands equally.", "next": "n2"}, {"text": "A shared defense pact against the coming threat from the north.", "next": "n2b"}, {"text": "A royal marriage to bind our houses together.", "next": "n2c"}]}, "n2": {"speaker": "king", "text": "Interesting. Queen Yssa, what say you?", "text_fr": "Intéressant. Reine Yssa, qu''en dites-vous ?", "choices": [{"text": "(wait for the queen''s response)", "next": "n3"}]}, "n2b": {"speaker": "king", "text": "The northern threat is real indeed. Queen Yssa, your thoughts?", "text_fr": "La menace du nord est bien réelle. Reine Yssa, votre avis ?", "choices": [{"text": "(wait for the queen''s response)", "next": "n3b"}]}, "n2c": {"speaker": "king", "text": "(surprised) A bold suggestion. Queen Yssa, how do you feel about that?", "text_fr": "(surpris) Une suggestion audacieuse. Reine Yssa, qu''en pensez-vous ?", "choices": [{"text": "(wait for the queen''s response)", "next": "n3c"}]}, "n3": {"speaker": "queen", "text": "Trade is wise, but I worry it won''t hold in times of true crisis.", "text_fr": "Le commerce est sage, mais je crains que ça ne tienne pas en cas de vraie crise.", "choices": [{"text": "Then let''s combine trade with a mutual defense clause.", "next": "n4"}]}, "n3b": {"speaker": "queen", "text": "A defense pact alone may create distrust without shared prosperity.", "text_fr": "Un pacte de défense seul pourrait créer de la méfiance sans prospérité partagée.", "choices": [{"text": "Agreed — let''s add trade terms to strengthen the bond.", "next": "n4"}]}, "n3c": {"speaker": "queen", "text": "Marriage builds strong ties, but it must be a choice, not just politics.", "text_fr": "Le mariage crée des liens forts, mais ça doit être un choix, pas juste de la politique.", "choices": [{"text": "Then let''s propose it as an option, with trade as the true foundation.", "next": "n4c"}]}, "n4": {"speaker": "king", "text": "A wise compromise. But my council will demand guarantees. What do you offer?", "text_fr": "Un compromis sage. Mais mon conseil exigera des garanties. Que proposez-vous ?", "choices": [{"text": "An annual summit to review the alliance and resolve disputes.", "next": "end_full"}]}, "n4c": {"speaker": "king", "text": "A thoughtful approach — foundation first, connection as it grows naturally.", "text_fr": "Une approche réfléchie — la fondation d''abord, le lien qui grandit naturellement.", "choices": [{"text": "Exactly, let''s build trust before anything more personal.", "next": "end_gradual"}]}, "end_full": {"speaker": "king", "text": "A wise compromise. Let this alliance be sealed today.", "text_fr": "Un compromis sage. Que cette alliance soit scellée aujourd''hui.", "end": true, "ending_label": "Alliance historique scellée 🤝"}, "end_gradual": {"speaker": "queen", "text": "This is how lasting peace is truly built — with patience.", "text_fr": "C''est ainsi qu''une paix durable se construit vraiment — avec patience.", "end": true, "ending_label": "Alliance fondée sur la confiance durable 🕊️"}}}'::jsonb, is_playable = true
where title = 'Une alliance à nouer entre plusieurs royaumes'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"villain": "le seigneur des ombres"}, "start_node": "n1", "nodes": {"n1": {"speaker": "villain", "text": "So, you''ve come at last. Will you fight, or will you try to reason with me?", "text_fr": "Alors, vous voilà enfin. Allez-vous vous battre, ou tenter de me raisonner ?", "choices": [{"text": "I''ll try to understand what drove you to this darkness.", "next": "n2"}, {"text": "I''m ready to fight, if that''s what it takes.", "next": "n2b"}, {"text": "I''ll offer you a chance to walk away, no bloodshed needed.", "next": "n2c"}]}, "n2": {"speaker": "villain", "text": "(pauses) ...No one has asked me that in a very long time.", "text_fr": "(marque une pause) ...Personne ne m''a demandé ça depuis très longtemps.", "choices": [{"text": "Then tell me your story, I''m listening.", "next": "n3"}]}, "n2b": {"speaker": "villain", "text": "Then let us settle this the old way!", "text_fr": "Alors réglons cela à l''ancienne !", "choices": [{"text": "(fight fiercely, but look for an opening to talk mid-battle)", "next": "n3b"}, {"text": "(commit fully to the battle, no hesitation)", "next": "n3c"}]}, "n2c": {"speaker": "villain", "text": "Walk away? After everything I''ve built here? You''re either brave or foolish.", "text_fr": "Partir ? Après tout ce que j''ai bâti ici ? Vous êtes soit courageux, soit imprudent.", "choices": [{"text": "Maybe both — but I truly believe there''s still good in you.", "next": "n3"}]}, "n3": {"speaker": "villain", "text": "I was betrayed by those I trusted most. The darkness... it was easier than the pain.", "text_fr": "J''ai été trahi par ceux en qui j''avais le plus confiance. Les ténèbres... c''était plus facile que la douleur.", "choices": [{"text": "Pain doesn''t have to become darkness. It''s not too late to choose differently.", "next": "end_redeemed"}]}, "n3b": {"speaker": "villain", "text": "(mid-fight, breathing heavily) Why do you hesitate to finish this?", "text_fr": "(en plein combat, essoufflé) Pourquoi hésitez-vous à en finir ?", "choices": [{"text": "Because I don''t believe violence is the only answer here.", "next": "end_mercy"}]}, "n3c": {"speaker": "villain", "text": "(the battle rages on intensely, until you finally overcome him)", "text_fr": "(le combat fait rage intensément, jusqu''à ce que vous le surpassiez enfin)", "choices": [{"text": "(stand victorious over your fallen enemy)", "next": "end_victory"}]}, "end_redeemed": {"speaker": "villain", "text": "Perhaps... perhaps there is another way. Thank you, traveler.", "text_fr": "Peut-être... peut-être y a-t-il une autre voie. Merci, voyageur.", "end": true, "ending_label": "Rédemption inattendue 🌅"}, "end_mercy": {"speaker": "villain", "text": "(lowers weapon) Mercy... I haven''t felt that in years. You''ve won something greater than a fight.", "text_fr": "(baisse son arme) La pitié... je n''ai pas ressenti ça depuis des années. Vous avez gagné quelque chose de plus grand qu''un combat.", "end": true, "ending_label": "Victoire par la compassion 💫"}, "end_victory": {"speaker": "villain", "text": "You have won... this land is free once more.", "text_fr": "Vous avez gagné... cette terre est de nouveau libre.", "end": true, "ending_label": "Victoire héroïque ⚔️"}}}'::jsonb, is_playable = true
where title = 'Un affrontement final avec plusieurs issues'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
